itemMappings = {}

def addMapping(item):
	keyFormat = item['data']['target']['path'].replace("/", "_") if item['data']['target']['path'] is not None else ''
	keyFormat = keyFormat.replace(" ", "__")
	indexStrs = list(filter(None, item['data']['index']))
	if len(indexStrs) > 1: itemMappings[keyFormat] = "/".join(indexStrs)
	else: itemMappings[keyFormat] = indexStrs[0]

def traverseTree(level):
	for item in level:
		if isinstance(item, str): continue
		if item['data']['target']: addMapping(item)
		if len(item['items']): 	traverseTree(item['items'])

traverseTree(value)

return itemMappings


search = value['search'] or ''
hierarchy = value['hierarchy']

currentViewPath = self.parent.custom.currentViewPath

def checkIfCurrentPathInItem(item):
	if item.has_key('target') and item['target']['path'] == currentViewPath: return True
	if item.has_key('children'): 
		for item in item['children']:
			if checkIfCurrentPathInItem(item): return True

	return False

def translateItem(item, index, parentIndices):
	targetPath = item["target"]["path"] if item.has_key("target") else None
	isSearchPath = search.lower() in item["label"].lower()
	isCurrentInPath = checkIfCurrentPathInItem(item)

	return {
		"label": item["label"],
		"data": {"target": item["target"] if item.has_key("target") else '', "display": isSearchPath or isCurrentInPath, 'index': parentIndices + [str(index)]},
		"expanded": isCurrentInPath,
		"items": [],
		"icon": {"path": item["icon"], "color": ""}
	}

def buildTreeLevel(items, parent):
	translatedItems = []
	indexCounter = 0
	for item in items:
		if not item.has_key('enabled') or (item.has_key('enabled') and item['enabled']):
			translatedItem = translateItem(item, indexCounter, parent["data"]["index"])
			#Call a function to find out if the currentViewPath is contained within this item or its children ONLY if this item is a folder

			if item.has_key('children'): translatedItem['items'] = buildTreeLevel(item['children'], translatedItem)
			for i in range(len(translatedItem['items'])):
				if translatedItem['items'][i]['data']['display']: translatedItem['data']['display'] = True
				if translatedItem['items'][i]['expanded']: translatedItem['expanded'] = True
			if translatedItem['data']['display']:
				if search != '': translatedItem['expanded'] = True		
				translatedItems.append(translatedItem)
				indexCounter += 1
	return translatedItems

hierarchyRoot = {"data": {"index": []}}
return buildTreeLevel(hierarchy, hierarchyRoot)

